INSERT INTO lessons (id, title, content_html, category_id) VALUES
  (
    'd4000001-0000-4000-8000-000000000001',
    'أركان الجملة',
    '<div class="lesson-page"><h2>ما هي أركان الجملة؟</h2><p>الجملة الفعلية في اللغة العربية تحتوي على أركان أساسية لا تكتمل الجملة بدونها. هذه الأركان هي: <strong>الفعل</strong> و<strong>الفاعل</strong> و<strong>المفعول به</strong> (إن وُجد).</p><p>الفعل هو الحدث، والفاعل من قام به، والمفعول به من وقع عليه الفعل.</p></div><div class="lesson-page"><h2>تعريف كل ركن</h2><p><strong>الفعل:</strong> كلمة تدل على حدث مقترن بزمن (ماضٍ، مضارع، أمر). مثل: جلس، يلعب، اقرأ.</p><p><strong>الفاعل:</strong> اسم مرفوع يأتي بعد الفعل ويدل على من قام بالفعل. مثل: الولد في «جلس الولد».</p><p><strong>المفعول به:</strong> اسم منصوب يقع عليه الفعل. مثل: التفاحة في «أكل محمد التفاحة».</p></div><div class="lesson-page"><h2>مثال تطبيقي</h2><p>في الجملة: <strong>جلس الولد</strong></p><ul><li>جلس → فعل (ماضٍ)</li><li>الولد → فاعل</li></ul><p>في الجملة: <strong>أكل محمد التفاحة</strong></p><ul><li>أكل → فعل</li><li>محمد → فاعل</li><li>التفاحة → مفعول به</li></ul><p>بممارسة التمارين ستتمكن من تمييز كل ركن بسهولة.</p></div>',
    'a1000003-0000-4000-8000-000000000003'
  );
